fn solve(word: Vec<char>) -> Vec<char> {
    // Define the two sets as arrays or slices for membership check
    // Using match or a function for membership check is simple and efficient here
    
    // Function to check if a char belongs to Set A
    fn in_set_a(c: char) -> bool {
        matches!(c, 'A' | 'E' | 'F' | 'H' | 'I' | 'K' | 'L' | 'M' | 'N' | 'T' | 'V' | 'W' | 'X' | 'Y' | 'Z')
    }

    // Function to check if a char belongs to Set B
    fn in_set_b(c: char) -> bool {
        matches!(c, 'B' | 'C' | 'D' | 'G' | 'J' | 'O' | 'P' | 'Q' | 'R' | 'S' | 'U')
    }

    if word.is_empty() {
        // According to problem statement, input length >= 1. Handle gracefully.
        // Return "NO" since no characters to determine the set.
        return "NO".chars().collect();
    }

    // Determine which set the first character belongs to
    let first_char = word[0];
    let set_a_candidate = in_set_a(first_char);
    let set_b_candidate = in_set_b(first_char);

    // If the first character doesn't belong to any of sets A or B, immediate NO
    if !set_a_candidate && !set_b_candidate {
        return "NO".chars().collect();
    }

    // Check all subsequent characters belong to the same set as the first character
    let all_in_same_set = word.iter().all(|&c| {
        if set_a_candidate {
            in_set_a(c)
        } else {
            in_set_b(c)
        }
    });

    if all_in_same_set {
        "YES".chars().collect()
    } else {
        "NO".chars().collect()
    }
}